/* Identidade Liliane Amarante: cinza #373435, sálvia #999e71, verde #334632, off-white #f3f8ea, preto #282829 */
:root{
  --bg:#f3f8ea;--fg:#282829;--muted:#5b5e57;--line:#d6ddc4;--card:#fbfdf6;
  --tit:#334632;--det:#59603a;--accent:#334632;--accent-fg:#f3f8ea;
  --pill:#334632;--pill-fg:#f3f8ea;--sage:#999e71;--stage:#22281f;
  --aj-bg:#efe9c4;--aj-fg:#54450f;--aj-bd:#a8963a;
  --ok-bg:#d3e4c1;--ok-fg:#1f3a1f;--ok-bd:#334632;
  --no-bg:#373435;--no-fg:#f3f8ea;--no-bd:#373435;
  --display:'Poppins','Trebuchet MS',system-ui,sans-serif;
  --body:'Inter',system-ui,-apple-system,'Segoe UI',sans-serif;
  --serif:'Cormorant Garamond',Georgia,serif;
}
@media (prefers-color-scheme:dark){
  :root:not([data-theme="light"]){
    --bg:#1d221c;--fg:#e8eddc;--muted:#b0b8a0;--line:#39432f;--card:#262d24;
    --tit:#c9cf9f;--det:#b3b98c;--accent:#999e71;--accent-fg:#1d221c;
    --pill:#999e71;--pill-fg:#1d221c;--sage:#6c7352;--stage:#12160f;
    --aj-bg:#4a4326;--aj-fg:#efe3a3;--aj-bd:#c9b45a;
    --ok-bg:#2f4a2e;--ok-fg:#d3e8c0;--ok-bd:#999e71;
    --no-bg:#4a4647;--no-fg:#efebe9;--no-bd:#8c8788;
    color-scheme:dark;
  }
}
:root[data-theme="dark"]{
  --bg:#1d221c;--fg:#e8eddc;--muted:#b0b8a0;--line:#39432f;--card:#262d24;
  --tit:#c9cf9f;--det:#b3b98c;--accent:#999e71;--accent-fg:#1d221c;
  --pill:#999e71;--pill-fg:#1d221c;--sage:#6c7352;--stage:#12160f;
  --aj-bg:#4a4326;--aj-fg:#efe3a3;--aj-bd:#c9b45a;
  --ok-bg:#2f4a2e;--ok-fg:#d3e8c0;--ok-bd:#999e71;
  --no-bg:#4a4647;--no-fg:#efebe9;--no-bd:#8c8788;
  color-scheme:dark;
}

